import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('statement lists issued invoices for a customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv1, []).value;

  const result = statement('C-001', [issued], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued.number);
  assert.equal(result.value.invoices[0].issueDate, '2025-01-15');
  assert.equal(result.value.invoices[0].dueDate, issued.dueDate);
  assert.equal(result.value.invoices[0].total, invoiceTotals(issued).total);
  assert.equal(result.value.invoices[0].due, invoiceTotals(issued).total);
});

test('statement includes multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = statement('C-001', [issued1, issued2], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].issueDate, '2025-01-15');
  assert.equal(result.value.invoices[1].issueDate, '2025-02-15');
});

test('statement sorts invoices by issueDate', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-03-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;
  const issued3 = issueInvoice(inv3, ['INV-2025-0002']).value;

  const result = statement('C-001', [issued1, issued2, issued3], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].issueDate, '2025-01-15');
  assert.equal(result.value.invoices[1].issueDate, '2025-02-15');
  assert.equal(result.value.invoices[2].issueDate, '2025-03-15');
});

test('statement filters by asOf date', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = statement('C-001', [issued1, issued2], '2025-02-28');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2025-01-15');
});

test('statement includes invoice on asOf date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = statement('C-001', [issued], '2025-01-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = statement('C-001', [inv], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const total = invoiceTotals(issued).total;
  const paid = recordPayment(issued, { amount: total, date: '2025-01-20' }).value;

  const result = statement('C-001', [paid], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement includes partially paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const total = invoiceTotals(issued).total;
  const partial = recordPayment(issued, { amount: Math.floor(total / 2), date: '2025-01-20' }).value;

  const result = statement('C-001', [partial], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].due, balanceDue(partial));
});

test('statement filters by customerId', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = statement('C-001', [issued1, issued2], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued1.number);
});

test('statement normalizes customerId', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = statement('c-001 ', [issued], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
});

test('statement calculates totalDue', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = statement('C-001', [issued1, issued2], '2025-12-31');

  assert.equal(result.ok, true);
  const expectedTotal = invoiceTotals(issued1).total + invoiceTotals(issued2).total;
  assert.equal(result.value.totalDue, expectedTotal);
});

test('statement with partial payments reduces totalDue', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const total1 = invoiceTotals(issued1).total;
  const partial1 = recordPayment(issued1, { amount: Math.floor(total1 / 2), date: '2025-01-20' }).value;

  const result = statement('C-001', [partial1, issued2], '2025-12-31');

  assert.equal(result.ok, true);
  const expectedTotal = balanceDue(partial1) + invoiceTotals(issued2).total;
  assert.equal(result.value.totalDue, expectedTotal);
});

test('statement returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = statement('C-999', [], '2025-12-31');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement with no matching invoices', () => {
  const result = statement('C-001', [], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement includes full invoice details', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = statement('C-001', [issued], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  const inv_item = result.value.invoices[0];
  assert.ok(inv_item.number);
  assert.equal(inv_item.issueDate, '2025-01-15');
  assert.equal(inv_item.dueDate, '2025-01-29');
  assert.ok(typeof inv_item.total === 'number');
  assert.ok(typeof inv_item.due === 'number');
});

