  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2025-01-15');
});

test('statement includes invoice on asOf date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = statement('C-001', [issued], '2025-01-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const result = statement('C-001', [inv], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const total = invoiceTotals(issued).total;
  const paid = recordPayment(issued, { amount: total, date: '2025-01-20' }).value;

  const result = statement('C-001', [paid], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement includes partially paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const total = invoiceTotals(issued).total;
  const partial = recordPayment(issued, { amount: Math.floor(total / 2), date: '2025-01-20' }).value;

  const result = statement('C-001', [partial], '2025-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].due, balanceDue(partial));
});

test('statement filters by customerId', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

